=[[tasknpc001]],["awardnpc"]=[[awardnpc001]],["name"]=[[白驼山]],["dsc"]=[[这里是白驼山庄的后院，居住着门派中负责俗务的长老和执事，环境清幽，别有洞天。]]},["2"]={["position"]=[[普济院]],["tasknpc"]=[[tasknpc002]],["awardnpc"]=[[awardnpc002]],["name"]=[[天龙寺]],["dsc"]=[[这里是普济院，寺里负责俗务的长老和知客僧就住在这里。]]},["3"]={["position"]=[[下院]],["tasknpc"]=[[tasknpc003]],["awardnpc"]=[[awardnpc003]],["name"]=[[峨眉派]],["dsc"]=[[这里是峨眉的下院，居住着门派中负责俗务的长老和执事，另外还有一些专事生产、维持着门派运转的外围弟子，也住在这里。]]},["4"]={["position"]=[[养心院]],["tasknpc"]=[[tasknpc004]],["awardnpc"]=[[awardnpc004]],["name"]=[[丐帮]],["dsc"]=[[这里是养心院，帮里几位负责俗务的长老就常年居住在这里。院子由几间精舍组成，闹中取静，别有一番风味。]]},["5"]={["position"]=[[偏厅]],["tasknpc"]=[[tasknpc005]],["awardnpc"]=[[awardnpc005]],["name"]=[[古墓派]],["dsc"]=[[这是古墓里的一间不起眼的偏厅，居住着两位负责俗务的长老名宿。]]},["6"]={["position"]=[[紫霞峰]],["tasknpc"]=[[tasknpc006]],["awardnpc"]=[[awardnpc006]],["name"]=[[华山派]],["dsc"]=[[这里是紫霞峰，是门派里负责俗务的长老们起居的地方，常年云雾缭绕，宛若仙境。]]},["7"]={["position"]=[[息心峰]],["tasknpc"]=[[tasknpc007]],["awardnpc"]=[[awardnpc007]],["name"]=[[昆仑派]],["dsc"]=[[这里是息心峰，是门派里负责俗务的长老们起居的地方，地形陡峭，深藏在云雾之间，扼守着门派进出的咽喉之地。]]},["8"]={["position"]=[[圣火居]],["tasknpc"]=[[tasknpc008]],["awardnpc"]=[[awardnpc008]],["name"]=[[明教]],["dsc"]=[[这里是圣火居，是一个占地甚广的院落，几位负责俗务的长老名宿就住在这里，是本教内外消息流转最快的地方。]]},["9"]={["position"]=[[后院]],["tasknpc"]=[[tasknpc009]],["awardnpc"]=[[awardnpc009]],["name"]=[[雪山寺]],["dsc"]=[[这里是雪山寺的后院，居住着门派中负责俗务的长老和几位知客僧，环境清幽，别有洞天。]]},["10"]={["position"]=[[凤凰居]],["tasknpc"]=[[tasknpc010]],["awardnpc"]=[[awardnpc010]],["name"]=[[慕容山庄]],["dsc"]=[[这里是凤凰居，是一排典雅别致的精舍，几位负责俗务的长老和执事就居住在这里。]]},["11"]={["position"]=[[后院]],["tasknpc"]=[[tasknpc011]],["awardnpc"]=[[awardnpc011]],["name"]=[[全真教]],["dsc"]=[[这里是后院，居住着教中负责俗务的道长和外门弟子，环境清幽，别有洞天。]]},["12"]={["position"]=[[黑水峰]],["tasknpc"]=[[tasknpc012]],["awardnpc"]=[[awardnpc012]],["name"]=[[日月神教]],["dsc"]=[[这里是黑水峰，是教里负责俗务的长老们起居的地方，地形险恶，易守难攻。]]},["13"]={["position"]=[[菩提院]],["tasknpc"]=[[tasknpc013]],["awardnpc"]=[[awardnpc013]],["name"]=[[少林派]],["dsc"]=[[这里是菩提院，寺里负责俗务的长老和知客僧就居住在这里，环境清幽，别有一番禅意。]]},["14"]={["position"]=[[后院]],["tasknpc"]=[[tasknpc014]],["awardnpc"]=[[awardnpc014]],["name"]=[[唐门]],["dsc"]=[[这里是后院，门派里几位负责俗务的长老就居住在这里，院子的环境森严古朴，透着一种年深日久的沧桑感。]]},["15"]={["position"]=[[落英湾]],["tasknpc"]=[[tasknpc015]],["awardnpc"]=[[awardnpc015]],["name"]=[[桃花岛]],["dsc"]=[[这里是落英湾，是一处占地甚广的院落，居住着几位负责俗务的长老，这里环境优美，视野开阔，风水极佳。]]},["16"]={["position"]=[[聚义庄]],["tasknpc"]=[[tasknpc016]],["awardnpc"]=[[awardnpc016]],["name"]=[[铁掌帮]],["dsc"]=[[这里是聚义庄，帮里负责俗务的长老和名宿就居住于此。庄子依山傍水，风景宜人。]]},["17"]={["position"]=[[三清殿]],["tasknpc"]=[[tasknpc017]],["awardnpc"]=[[awardnpc017]],["name"]=[[武当派]],["dsc"]=[[这里是三清殿，门派里几位负责俗务的长老就常年居住在这里。四周遍植松柏，静谧中透着一种森严气象。]]},["18"]={["position"]=[[五仙庄]],["tasknpc"]=[[tasknpc018]],["awardnpc"]=[[awardnpc018]],["name"]=[[五毒教]],["dsc"]=[[这里是五仙庄，教中几位负责俗务的长老就常年居住在这里。庄子周围种植着很多寻常难得一见的花木。]]},["19"]={["position"]=[[折梅岭]],["tasknpc"]=[[tasknpc019]],["awardnpc"]=[[awardnpc019]],["name"]=[[天山派]],["dsc"]=[[这里是折梅岭，门派里几位负责俗务的长老就常年居住在这里。岭上种植着很多梅花，宛若仙境。]]},["20"]={["position"]=[[毒龙峰]],["tasknpc"]=[[tasknpc020]],["awardnpc"]=[[awardnpc020]],["name"]=[[星宿派]],["dsc"]=[[这里是毒龙峰，门派里几位负责俗务的长老就常年居住在这里。峰上常年云雾缭绕，层峦叠嶂，别有洞天。]]},["21"]={["position"]=[[伏羲阁]],["tasknpc"]=[[tasknpc021]],["awardnpc"]=[[awardnpc021]],["name"]=[[崆峒派]],["dsc"]=[[这里是伏羲阁，门派里几位负责俗务的长老就常年居住在这里。周围有密林修竹，有奇石清泉，景色宜人。]]},["22"]={["position"]=[[巨浪堂]],["tasknpc"]=[[tasknpc022]],["awardnpc"]=[[awardnpc022]],["name"]=[[海鲸帮]],["dsc"]=[[这里是巨浪堂，门派里几位负责俗务的长老就常年居住在这里。这里是门派内外信息流转最快的地方。]]},["23"]={["position"]=[[阴曹殿]],["tasknpc"]=[[tasknpc023]],["awardnpc"]=[[awardnpc023]],["name"]=[[幽冥教]],["dsc"]=[[这里是阴曹殿，门派里几位负责俗务的长老就常年居住在这里。这里常年不见日光，从里到外透着一种阴冷的气息。]]},["24"]={["position"]=[[后院]],["tasknpc"]=[[tasknpc024]],["awardnpc"]=[[awardnpc024]],["name"]=[[官府]],["dsc"]=[[这里是后院，门派里几位负责俗务的长老就常年居住在这里，环境肃穆庄重，让人不自觉地屏息凝神。]]},["25"]={["position"]=[[新月楼]],["tasknpc"]=[[tasknpc025]],["awardnpc"]=[[awardnpc025]],["name"]=[[落月山庄]],["dsc"]=[[这里是新月楼，门派里几位负责俗务的长老就常年居住在这里，这里有数人正在交流庄内事务。]]}},["Sheet1"]={["1"]={["Collectjobroom"]=[[fb02;fb02_04]],["festivarate"]=[[40;10;50;0,40;